head.b:skin:
    /* Landing palette (extension-landing-blogger-snippet parity) + blog tokens */
    :root {
      --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
      --red: #c41e3a;
      --el-bg: #eef6ef;
      --el-card: #ffffff;
      --el-text: #132818;
      --el-muted: #2a3a30;
      --el-g: #1b5e20;
      --el-gm: #2e7d32;
      --el-gb: #43a047;
      --el-bd: #b2dfbc;
      --el-bds: #e8f5e9;
      --el-sh: 0 10px 40px rgba(27, 94, 32, 0.08);
      --el-shh: 0 20px 50px rgba(27, 94, 32, 0.14);
      --black: #0a0a0a;
      --white: #ffffff;
      --bg: var(--el-bg);
      --bg2: var(--el-bg);
      --card: var(--el-card);
      --text: var(--el-text);
      --muted: var(--el-muted);
      --green: var(--el-g);
      --green-mid: var(--el-gm);
      --green-bright: var(--el-gb);
      --firefox: #ff7139;
      --border: var(--el-bd);
      --border-soft: var(--el-bds);
      --shadow: var(--el-sh);
      --shadow-hover: var(--el-shh);
      --radius: 20px;
      --topbar-h: 56px;
    }
    @media (prefers-color-scheme: dark) {
      :root {
        --el-bg: #0d160f;
        --el-card: #1a281d;
        --el-text: #e8f5e9;
        --el-muted: #c8e6c9;
        --el-bd: #2e4a32;
        --el-bds: #1e2e22;
        --el-sh: 0 12px 40px rgba(0, 0, 0, 0.45);
        --el-shh: 0 20px 56px rgba(0, 0, 0, 0.55);
        --bg: var(--el-bg);
        --bg2: var(--el-bg);
        --card: var(--el-card);
        --text: var(--el-text);
        --muted: var(--el-muted);
        --border: var(--el-bd);
        --border-soft: var(--el-bds);
        --shadow: var(--el-sh);
        --shadow-hover: var(--el-shh);
        --green-mid: #81c784;
        --green-bright: #a5d6a7;
      }
      .card-icon { background: linear-gradient(145deg, #1b3320, #243d28) !important; }
      .topbar { background: rgba(13, 22, 15, 0.92) !important; border-color: var(--border) !important; }
      .lp-readbar { background: linear-gradient(90deg, #12171d 0%, #ff3131 22%, #2e7d32 50%, #1b5e20 72%, #0d160f 100%); }
      .ext-lp-ic { background: linear-gradient(145deg, #1b3320, #243d28) !important; }
      .ext-lp-ic.ext-lp-ic-pic { background: #fff !important; }
      .topbar-sub { color: #c8e6c9; }
      .topbar-title { color: #e8f5e9; -webkit-text-fill-color: #e8f5e9; }
      /* Dark override for the hardcoded light hero gradient */
      .hero {
        background:
          linear-gradient(135deg, rgba(37, 99, 235, 0.09) 0%, transparent 48%),
          linear-gradient(225deg, rgba(196, 30, 58, 0.08) 0%, transparent 40%),
          linear-gradient(165deg, var(--el-card) 0%, var(--el-bg) 100%);
      }
      /* Dark override for the hardcoded light lang strip gradient */
      .lang-strip {
        background: linear-gradient(120deg, var(--el-card) 0%, rgba(30, 46, 34, 0.85) 55%, rgba(26, 40, 29, 0.9) 100%);
      }
    }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
    }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    .lp-readbar {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      height: 5px;
      z-index: 100;
      pointer-events: none;
      background: linear-gradient(90deg, #12171d 0%, #ff3131 18%, #1b5e20 42%, #2e7d32 62%, #43a047 82%, #12171d 100%);
      box-shadow: 0 1px 0 rgba(18, 23, 29, 0.25);
    }
    body {
      margin: 0;
      font-family: var(--font-sans);
      background: var(--bg2);
      color: var(--text);
      line-height: 1.55;
      min-height: 100vh;
    }
    body::before {
      content: "";
      position: fixed;
      inset: 0;
      background:
        radial-gradient(ellipse 90% 55% at 50% -25%, rgba(27, 94, 32, 0.08), transparent),
        radial-gradient(ellipse 50% 45% at 100% 20%, rgba(46, 125, 50, 0.05), transparent),
        radial-gradient(ellipse 45% 40% at 0% 90%, rgba(19, 40, 24, 0.04), transparent);
      pointer-events: none;
      z-index: 0;
    }
    .wrap {
      position: relative;
      z-index: 1;
      max-width: 1080px;
      margin: 0 auto;
      padding: calc(var(--topbar-h) + 23px) 20px 64px;
    }
    .topbar {
      position: fixed;
      top: 3px;
      left: 0;
      right: 0;
      z-index: 50;
      height: var(--topbar-h);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 22px;
      background: rgba(255, 255, 255, 0.85);
      backdrop-filter: blur(14px) saturate(1.2);
      -webkit-backdrop-filter: blur(14px) saturate(1.2);
      border-bottom: 1px solid var(--border-soft);
    }
    .topbar-brand {
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: 10px;
      min-width: 0;
    }
    .topbar-logo {
      width: 40px;
      height: 40px;
      border-radius: 12px;
      object-fit: cover;
      border: 1px solid var(--el-bd);
      box-shadow: 0 1px 4px rgba(27, 94, 32, 0.12);
      flex-shrink: 0;
    }
    /* Full wordmark: avoid cropping; hide duplicate text title next to image */
    .topbar-logo.topbar-logo-wordmark {
      width: auto;
      height: 30px;
      max-width: min(150px, 40vw);
      object-fit: contain;
      background: rgba(18, 23, 29, 0.06);
      position: relative;
      top: 1px;
    }
    .topbar-logo-wordmark ~ .topbar-brand-stack .topbar-title {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }
    .topbar-logo-fallback {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 40px;
      height: 40px;
      border-radius: 12px;
      font-size: 1.35rem;
      line-height: 1;
      background: linear-gradient(145deg, #e8f5e9, #c8e6c9);
      border: 1px solid var(--el-bd);
      flex-shrink: 0;
    }
    .topbar-brand-stack { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 1px; min-width: 0; text-align: left; }
    .topbar-title {
      font-weight: 800;
      font-size: 1.05rem;
      letter-spacing: -0.03em;
      line-height: 1.15;
      color: var(--el-text);
      -webkit-text-fill-color: var(--el-text);
    }
    .topbar-sub {
      font-size: 0.62rem;
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      color: #1a2820;
    }
    .topbar-logo-fallback.topbar-initials {
      font-size: 0.7rem;
      font-weight: 800;
      color: #fff;
      background: linear-gradient(145deg, #5c1018, #1a0a0c);
      font-family: var(--font-sans);
    }
    .topbar-nav { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
    .topbar-nav a {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--muted);
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 44px;
      padding: 10px 14px;
      border-radius: 10px;
    }
    .topbar-nav a:hover { color: var(--green-mid); background: var(--border-soft); }
    .hero {
      text-align: center;
      padding: 42px 24px 50px;
      background:
        linear-gradient(135deg, rgba(37, 99, 235, 0.06) 0%, transparent 48%),
        linear-gradient(225deg, rgba(196, 30, 58, 0.05) 0%, transparent 40%),
        linear-gradient(165deg, #ffffff 0%, #fafafa 100%);
      border-radius: var(--radius);
      border: 1px solid var(--border);
      box-shadow: var(--shadow), 0 0 0 1px rgba(255, 255, 255, 0.5) inset;
      margin-bottom: 40px;
      position: relative;
      overflow: hidden;
    }
    .hero::after {
      content: "";
      position: absolute;
      bottom: 0;
      left: 8%;
      right: 8%;
      height: 3px;
      border-radius: 3px;
      background: linear-gradient(90deg, #0a0a0a, #c41e3a, #ffffff, #2563eb, #0a0a0a);
      opacity: 0.85;
    }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.68rem;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--green-mid);
      margin-bottom: 14px;
      padding: 6px 12px;
      background: var(--card);
      border-radius: 999px;
      border: 1px solid var(--border);
    }
    .hero h1 {
      font-weight: 800;
      font-size: clamp(1.85rem, 4.5vw, 2.5rem);
      letter-spacing: -0.035em;
      margin: 0 0 14px;
      line-height: 1.12;
    }
    .hero-lead {
      max-width: 540px;
      margin: 0 auto 22px;
      color: var(--muted);
      font-size: 1.08rem;
    }
    .hero-actions { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; align-items: center; }
    .btn-ghost {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 0.65rem 1.2rem;
      border-radius: 999px;
      font-weight: 600;
      font-size: 0.875rem;
      text-decoration: none;
      color: var(--green-mid);
      border: 2px solid var(--border);
      background: transparent;
      transition: background 0.2s, border-color 0.2s;
    }
    .btn-ghost:hover { background: var(--border-soft); border-color: var(--green-bright); }
    .trust {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px 20px;
      margin-bottom: 36px;
      font-size: 0.8rem;
      font-weight: 600;
      color: var(--muted);
    }
    .trust span {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 8px 14px;
      background: var(--card);
      border-radius: 999px;
      border: 1px solid var(--border);
      box-shadow: 0 2px 8px rgba(10, 10, 10, 0.06);
    }
    .store-strip {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px;
      margin-bottom: 36px;
    }
    .store-strip a {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 10px 16px;
      border-radius: 12px;
      font-size: 0.8rem;
      font-weight: 700;
      text-decoration: none;
      color: var(--text);
      background: var(--card);
      border: 1px solid var(--border);
      box-shadow: 0 2px 10px rgba(10, 10, 10, 0.06);
      transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
    }
    .store-strip a:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(37, 99, 235, 0.12);
      border-color: var(--green-bright);
    }
    .store-strip .s-firefox { border-left: 3px solid #ff7139; }
    .dev-tools-strip {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 8px;
      margin: 0 0 28px;
      padding: 0 4px;
    }
    .dev-tools-strip .dt-pill {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 8px 14px;
      border-radius: 999px;
      font-size: 0.72rem;
      font-weight: 700;
      text-decoration: none;
      color: var(--text);
      background: var(--card);
      border: 1px dashed var(--border);
      box-shadow: 0 1px 6px rgba(10, 10, 10, 0.05);
      transition: border-color 0.2s, box-shadow 0.2s;
    }
    .dev-tools-strip .dt-pill:hover {
      border-color: var(--green-bright);
      border-style: solid;
      box-shadow: 0 4px 14px rgba(37, 99, 235, 0.12);
    }
    .section-head {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 20px;
      min-height: 4.5rem;
      contain: layout style;
    }
    .section-head h2 {
      font-size: 1.35rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      margin: 0;
    }
    .section-head p { margin: 0; font-size: 0.9rem; color: var(--muted); }
    .grid {
      display: grid;
      gap: 22px;
      grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
    }
    .card {
      background: var(--card);
      border-radius: var(--radius);
      border: 1px solid var(--border);
      box-shadow: var(--shadow);
      padding: 22px 22px 20px;
      display: flex;
      flex-direction: column;
      transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.2s;
    }
    .card:hover {
      transform: translateY(-5px);
      box-shadow: var(--shadow-hover);
      border-color: var(--green-bright);
    }
    .card.featured {
      grid-column: 1 / -1;
      flex-direction: row;
      flex-wrap: wrap;
      align-items: flex-start;
      gap: 20px;
      padding: 26px;
    }
    @media (min-width: 720px) {
      .card.featured .card-body { flex: 1; min-width: 240px; }
    }
    .card-top { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 10px; }
    .card-icon {
      width: 56px;
      height: 56px;
      border-radius: 16px;
      background: linear-gradient(145deg, #ffffff, #dbeafe, #fecaca);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.55rem;
      flex-shrink: 0;
      border: 1px solid var(--border);
      box-shadow: inset 0 1px 0 #ffffff, 0 2px 10px rgba(10, 10, 10, 0.06);
    }
    .card h1 {
      font-size: 1.6rem;
      font-weight: 800;
      margin: 0 0 4px;
      letter-spacing: -0.025em;
      line-height: 1.2;
      color: var(--text);
    }
    .card h2, .card h2 a {
      font-size: 1.18rem;
      font-weight: 700;
      margin: 0 0 4px;
      letter-spacing: -0.02em;
      color: var(--text);
      text-decoration: none;
    }
    .card h2 a:hover { color: var(--green-mid); }
    .card .tag {
      font-size: 0.68rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.07em;
      color: var(--green-mid);
      margin-bottom: 6px;
    }
    .card-meta { font-size: 0.78rem; color: var(--muted); margin-bottom: 10px; }
    .card p, .post-body { margin: 0 0 16px; font-size: 0.93rem; color: var(--muted); flex: 1; }
    .post-body { color: var(--text); }
    .post-body img { max-width: 100%; height: auto; border-radius: 12px; }
    /* Static pages (About, Privacy…): no duplicate card header — body supplies title + layout */
    .static-page-article {
      grid-column: 1 / -1;
      width: 100%;
      margin: 0;
      padding: 0;
      background: transparent;
      border: none;
      box-shadow: none;
    }
    .static-page-article .post-static-page { margin-top: 0; }
    .card-actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
    a.btn-firefox {
      display: inline-flex !important;
      align-items: center;
      justify-content: center;
      gap: 0.45rem;
      padding: 0.68rem 1.35rem;
      border-radius: 999px;
      background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 40%, #1d4ed8 100%) !important;
      color: #ffffff !important;
      font-weight: 600 !important;
      font-size: 0.875rem !important;
      text-decoration: none !important;
      border: 1px solid #1e40af;
      box-shadow: 0 6px 22px rgba(37, 99, 235, 0.35);
      transition: filter 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
    }
    a.btn-firefox:hover { filter: brightness(1.08); transform: translateY(-2px); box-shadow: 0 12px 32px rgba(37, 99, 235, 0.45); }
    a.btn-store-firefox {
      background: linear-gradient(135deg, #991b1b 0%, #c41e3a 45%, #dc2626 100%) !important;
      border: 1px solid #7f1d1d !important;
      box-shadow: 0 4px 20px rgba(196, 30, 58, 0.4) !important;
    }
    a.btn-store-firefox:hover { box-shadow: 0 8px 28px rgba(220, 38, 38, 0.45) !important; }
    a.btn-firefox .fox-icon { font-size: 1.05rem; line-height: 1; flex-shrink: 0; }
    .link-store {
      font-size: 0.82rem;
      font-weight: 600;
      color: var(--green-mid);
      text-decoration: none;
      border-bottom: 1px solid transparent;
    }
    .link-store:hover { border-bottom-color: var(--green-mid); }
    .faq {
      margin-top: 48px;
      padding: 28px 24px;
      background: var(--card);
      border-radius: var(--radius);
      border: 1px solid var(--border);
      box-shadow: var(--shadow);
    }
    .faq h2 { font-size: 1.2rem; font-weight: 800; margin: 0 0 16px; text-align: center; }
    .faq details { border-bottom: 1px solid var(--border); padding: 14px 0; }
    .faq details:last-child { border-bottom: 0; }
    .faq summary {
      font-weight: 700;
      font-size: 0.95rem;
      cursor: pointer;
      list-style: none;
      min-height: 44px;
      padding: 12px 0;
      line-height: 1.4;
    }
    .faq summary::-webkit-details-marker { display: none; }
    .faq summary::after { content: "+"; float: inline-end; font-weight: 800; color: var(--green-mid); }
    .faq details[open] summary::after { content: "−"; }
    .faq details p { margin: 12px 0 0; font-size: 0.9rem; color: var(--muted); }
    .ext-lp-faq-full { margin: 18px 0 0; text-align: center; font-size: 0.92rem; }
    .foot {
      text-align: center;
      margin-top: 48px;
      padding-top: 28px;
      border-top: 1px solid var(--border);
      font-size: 0.84rem;
      color: var(--muted);
    }
    .foot a { color: var(--green-mid); font-weight: 600; text-decoration: none; }
    .foot a:hover { text-decoration: underline; }
    .foot-links { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px 8px; align-items: center; }
    .foot-links a {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 44px;
      padding: 8px 12px;
      border-radius: 10px;
    }
    .foot-links a:focus-visible { outline: 2px solid var(--green-mid); outline-offset: 2px; }
    .blog-pager {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 16px;
      margin-top: 32px;
      font-weight: 600;
    }
    .blog-pager a {
      color: var(--green-mid);
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 44px;
      padding: 10px 16px;
      border-radius: 10px;
    }
    .blog-pager a:hover { text-decoration: underline; background: var(--border-soft); }
    .post-comments { margin-top: 28px; padding: 24px; background: var(--card); border-radius: var(--radius); border: 1px solid var(--border); }
    .status-msg {
      text-align: center;
      padding: 18px 20px;
      color: var(--muted);
      background: var(--card);
      border: 1px dashed var(--border);
      border-radius: 14px;
      margin-bottom: 18px;
      font-size: 0.92rem;
    }
    .status-msg a { color: var(--green-mid); font-weight: 700; }
    .skip-link {
      position: absolute;
      left: 12px;
      top: -100px;
      z-index: 200;
      padding: 10px 16px;
      background: var(--green-mid);
      color: #fff !important;
      font-weight: 700;
      font-size: 0.875rem;
      border-radius: 10px;
      text-decoration: none;
      transition: top 0.2s;
    }
    .skip-link:focus { top: 12px; outline: 2px solid var(--green-bright); outline-offset: 2px; }
    .layout-grid {
      display: grid;
      gap: 28px;
      align-items: start;
      grid-template-columns: 1fr;
    }
    @media (min-width: 1024px) {
      .layout-grid { grid-template-columns: minmax(0, 1fr) minmax(260px, 320px); }
      .layout-sidebar { position: sticky; top: calc(var(--topbar-h) + 16px); }
    }
    .layout-main { min-width: 0; }
    /* Reduce CLS when posts grid is empty or nav message appears */
    #main.main.section .grid {
      min-height: 120px;
    }
    #main.main.section .status-msg {
      min-height: 2.75rem;
      box-sizing: border-box;
    }
    .breadcrumb { margin-bottom: 16px; font-size: 0.82rem; color: var(--muted); }
    .breadcrumb ol {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 8px;
      list-style: none;
      margin: 0;
      padding: 0;
    }
    .breadcrumb li:not(:last-child)::after { content: "/"; margin-left: 8px; color: var(--border); font-weight: 600; }
    .breadcrumb a { color: var(--green-mid); font-weight: 600; text-decoration: none; }
    .breadcrumb a:hover { text-decoration: underline; }
    .breadcrumb [aria-current='page'] { color: var(--text); font-weight: 700; max-width: 100%; }
    .stats-strip {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
      gap: 14px;
      margin-bottom: 32px;
    }
    .stats-strip .stat {
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 16px;
      text-align: center;
      box-shadow: var(--shadow);
    }
    .stats-strip .stat strong { display: block; font-size: 1.5rem; font-weight: 800; color: var(--green-mid); line-height: 1.2; }
    .stats-strip .stat span { font-size: 0.75rem; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }
    .rss-cta {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 32px;
      padding: 22px 24px;
      background: linear-gradient(135deg, var(--border-soft), var(--card));
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
    }
    .rss-cta h3 { margin: 0 0 6px; font-size: 1.05rem; font-weight: 800; }
    .rss-cta p { margin: 0; font-size: 0.9rem; color: var(--muted); max-width: 420px; }
    .rss-cta-actions { display: flex; flex-wrap: wrap; gap: 10px; }
    .card-thumb {
      display: block;
      margin: -6px -6px 14px;
      border-radius: 14px;
      overflow: hidden;
      border: 1px solid var(--border);
      aspect-ratio: 16 / 9;
      background: var(--border-soft);
    }
    .card-thumb img { width: 100%; height: 100%; object-fit: cover; vertical-align: middle; }
    .layout-sidebar .widget {
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 18px 16px 16px;
      margin-bottom: 18px;
    }
    .layout-sidebar .widget:last-child { margin-bottom: 0; }
    .layout-sidebar .widget-title {
      font-size: 0.95rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      margin: 0 0 14px;
      padding-bottom: 10px;
      border-bottom: 1px solid var(--border-soft);
      color: var(--text);
    }
    .layout-sidebar .widget-content { font-size: 0.88rem; color: var(--muted); }
    .layout-sidebar .widget-content a { color: var(--green-mid); font-weight: 600; text-decoration: none; }
    .layout-sidebar .widget-content a:hover { text-decoration: underline; }
    .layout-sidebar .widget-content ul { margin: 0; padding-left: 1.1rem; }
    .layout-sidebar .widget-content li { margin-bottom: 6px; }
    .layout-sidebar .dev-tools { scroll-margin-top: calc(var(--topbar-h) + 12px); }
    .layout-sidebar .dev-tools-intro { margin: 0 0 14px; font-size: 0.8rem; line-height: 1.45; color: var(--muted); }
    .layout-sidebar .dev-tools-group { margin-bottom: 16px; }
    .layout-sidebar .dev-tools-group:last-of-type { margin-bottom: 0; }
    .layout-sidebar .dev-tools-label {
      margin: 0 0 8px;
      font-size: 0.62rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--green-mid);
    }
    .layout-sidebar .dev-tools ul { list-style: none; padding-left: 0; margin: 0; }
    .layout-sidebar .dev-tools li { margin-bottom: 5px; }
    .layout-sidebar .dev-tools a {
      display: flex;
      align-items: center;
      min-height: 44px;
      padding: 10px 12px;
      border-radius: 10px;
      background: var(--border-soft);
      border: 1px solid var(--border);
      font-size: 0.8rem;
      font-weight: 600;
      line-height: 1.35;
      text-decoration: none !important;
      transition: border-color 0.2s, box-shadow 0.2s;
    }
    .layout-sidebar .dev-tools a:hover {
      border-color: var(--green-bright);
      box-shadow: 0 2px 10px rgba(37, 99, 235, 0.12);
      text-decoration: none !important;
    }
    .layout-sidebar input[type='text'],
    .layout-sidebar input[type='email'] {
      width: 100%;
      padding: 10px 12px;
      border-radius: 10px;
      border: 1px solid var(--border);
      font-family: inherit;
      font-size: 0.875rem;
      margin-bottom: 8px;
    }
    /* Blog search: 44px+ touch targets (Lighthouse a11y) */
    #BlogSearch1 .blog-search-form {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: stretch;
    }
    #BlogSearch1 .search-input {
      flex: 1 1 160px;
      min-width: 0;
      margin-bottom: 0;
    }
    #BlogSearch1 input[name='q'] {
      min-height: 48px !important;
      margin-bottom: 0;
      box-sizing: border-box;
    }
    #BlogSearch1 .search-action {
      min-height: 48px !important;
      min-width: 96px !important;
      padding: 0 20px !important;
      border-radius: 10px;
      border: 1px solid var(--el-bd);
      background: var(--el-gm);
      color: #fff;
      font-weight: 600;
      cursor: pointer;
      font-family: inherit;
      font-size: 0.875rem;
    }
    #BlogSearch1 .search-action:hover { filter: brightness(1.06); }
    #BlogSearch1 .search-action:focus-visible {
      outline: 2px solid var(--el-g);
      outline-offset: 2px;
    }
    /* Popular posts: list markup (avoid invalid role=feed from default snippetedPosts) */
    #PopularPosts1 .popular-posts-a11y ul.popular-posts-list {
      list-style: none;
      padding: 0;
      margin: 0;
    }
    #PopularPosts1 .popular-post-item { margin-bottom: 8px; }
    #PopularPosts1 .popular-post-item:last-child { margin-bottom: 0; }
    #PopularPosts1 .popular-post-row,
    #PopularPosts1 .popular-post-link-only {
      display: flex;
      align-items: center;
      gap: 10px;
      min-height: 44px;
      padding: 6px 8px;
      margin: 0 -4px;
      border-radius: 10px;
      text-decoration: none !important;
      color: var(--green-mid);
      font-weight: 600;
      line-height: 1.3;
    }
    #PopularPosts1 .popular-post-row:hover,
    #PopularPosts1 .popular-post-link-only:hover {
      background: var(--border-soft);
    }
    #PopularPosts1 .popular-post-thumb {
      width: 48px;
      height: 48px;
      border-radius: 8px;
      object-fit: cover;
      border: 1px solid var(--border);
      flex-shrink: 0;
    }
    #PopularPosts1 .popular-post-title { flex: 1; min-width: 0; }
    .layout-sidebar .follow-by-email-submit {
      border-radius: 999px !important;
      background: linear-gradient(135deg, #2563eb, #1e40af) !important;
      color: #fff !important;
      font-weight: 600 !important;
      border: none !important;
      padding: 10px 18px !important;
      cursor: pointer;
    }
    .foot-copy { margin: 16px 0 0; font-size: 0.8rem; color: var(--muted); }
    .post-body h2, .post-body h3, .post-body h4 { margin-top: 1.4em; margin-bottom: 0.5em; line-height: 1.25; }
    .post-body a { color: var(--green-mid); font-weight: 600; }
    .post-body blockquote { margin: 1rem 0; padding: 12px 16px; border-left: 4px solid #c41e3a; background: var(--border-soft); border-radius: 0 12px 12px 0; }
    .post-body pre, .post-body code { font-family: ui-monospace, monospace; font-size: 0.88em; }
    .post-body pre { overflow-x: auto; padding: 14px; border-radius: 12px; background: var(--border-soft); border: 1px solid var(--border); }
    .catalog-compact { margin-bottom: 28px; }
    .catalog-compact .catalog-list { margin: 12px 0 0; padding-left: 1.2rem; color: var(--muted); font-size: 0.93rem; }
    .catalog-compact .catalog-list li { margin-bottom: 8px; }
    .catalog-compact .catalog-list a { font-weight: 600; color: var(--green-mid); text-decoration: none; }
    .catalog-compact .catalog-list a:hover { text-decoration: underline; }
    .publish-guide { margin-bottom: 28px; }
    .publish-guide h2 { font-size: 1.15rem; font-weight: 800; margin: 0 0 14px; letter-spacing: -0.02em; }
    .publish-guide ol { margin: 0; padding-left: 1.25rem; color: var(--text); font-size: 0.92rem; line-height: 1.5; }
    .publish-guide li { margin-bottom: 12px; }
    .publish-guide li strong { color: var(--green-mid); }
    .publish-guide .label-hint {
      display: block;
      margin-top: 6px;
      padding: 10px 12px;
      background: var(--border-soft);
      border-radius: 10px;
      font-size: 0.8rem;
      color: var(--muted);
      font-family: ui-monospace, monospace;
      word-break: break-word;
    }
    .tag-row { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; align-items: center; }
    .tag-row .tag { margin-bottom: 0; font-size: 0.62rem; padding: 4px 8px; border-radius: 6px; background: var(--border-soft); }
    .lang-strip {
      margin-bottom: 28px;
      padding: 18px 20px;
      border-radius: var(--radius);
      border: 1px solid var(--border);
      background: linear-gradient(120deg, #ffffff 0%, rgba(219, 234, 254, 0.85) 50%, rgba(254, 226, 226, 0.7) 100%);
      box-shadow: var(--shadow);
    }
    .lang-strip-head {
      font-size: 0.72rem;
      font-weight: 800;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--green-mid);
      margin-bottom: 12px;
    }
    .lang-strip p { margin: 0; font-size: 0.88rem; color: var(--muted); line-height: 1.55; padding: 14px 0; border-top: 1px solid var(--border-soft); }
    .lang-strip p:first-of-type { border-top: 0; padding-top: 0; }
    .lang-strip p:last-child { padding-bottom: 0; }
    .lang-strip-ar {
      font-family: "Noto Sans Arabic", sans-serif;
      font-size: 0.95rem;
      line-height: 1.65;
    }
    /* Hard contrast on landing (Blogger section text can be forced light) */
    #content .ext-lp-root { color: var(--el-text); isolation: isolate; }
    #content .ext-lp-hero h1 { color: var(--el-text); }
    #content .ext-lp-hero-name { color: var(--el-text); }
    #content .ext-lp-hero-hub { color: var(--el-muted); }
    #content .ext-lp-hero-edition { color: #c62828; }
    #content .ext-lp-lead { color: var(--el-muted); }
    #content .ext-lp-lead strong { color: var(--el-text); }
    #content .ext-lp-badge { color: var(--el-gm); }
    #content .ext-lp-ghost {
      color: var(--el-gm);
      border-color: var(--el-bd);
      background: rgba(255, 255, 255, 0.5);
    }
    #content .ext-lp-ghost:hover { background: var(--el-bds); }
    #content .ext-lp-trust span { color: var(--el-muted); }
    @media (prefers-color-scheme: dark) {
      #content .ext-lp-root,
      #content .ext-lp-hero h1 { color: #e8f5e9; }
      #content .ext-lp-hero-name { color: #ffffff; }
      #content .ext-lp-hero-hub { color: #c8e6c9; }
      #content .ext-lp-hero-edition { color: #ff8a80; }
      #content .ext-lp-lead { color: #a5d6a7; }
      #content .ext-lp-lead strong { color: #e8f5e9; }
      #content .ext-lp-badge { color: #a5d6a7; }
      #content .ext-lp-ghost {
        color: #c8e6c9;
        border-color: #2e4a32;
        background: rgba(26, 40, 29, 0.6);
      }
      #content .ext-lp-ghost:hover { background: #1e2e22; }
      #content .ext-lp-trust span { color: #c8e6c9; }
    }

    /* extension-landing-blogger-snippet layout */
    .ext-lp-root {
      box-sizing: border-box;
      margin: 0 auto 2rem;
      max-width: 1080px;
      padding: 0 4px 8px;
    }
    .ext-lp-hero {
      text-align: center;
      padding: 2.2rem 1.25rem 2.6rem;
      background: linear-gradient(165deg, var(--el-bds) 0%, var(--el-card) 50%);
      border-radius: var(--radius);
      border: 1px solid var(--el-bd);
      box-shadow: var(--el-sh);
      margin-bottom: 1.75rem;
    }
    .ext-lp-hero-brand { margin-bottom: 0.35rem; }
    .ext-lp-hero-logo-wrap { display: flex; flex-direction: column; align-items: center; gap: 0.45rem; margin-bottom: 0.75rem; }
    .ext-lp-hero-logo {
      width: 80px;
      height: 80px;
      border-radius: 18px;
      object-fit: cover;
      border: 1px solid var(--el-bd);
      box-shadow: var(--el-sh);
    }
    .ext-lp-hero-logo.ext-lp-hero-logo-wordmark {
      width: min(200px, 58vw);
      height: auto;
      max-width: 100%;
      aspect-ratio: 1;
      object-fit: contain;
      border-radius: 14px;
      background: rgba(18, 23, 29, 0.06);
      display: block;
      margin-block-start: 4px;
      margin-inline: auto;
      transform: translateY(2px);
    }
    .ext-lp-hero-brandlines {
      margin: 0.5rem 0 0;
      text-align: center;
      max-width: 28rem;
      margin-inline: auto;
    }
    .ext-lp-hero-name {
      margin: 0;
      font-size: clamp(1.4rem, 4.2vw, 1.85rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.1;
      color: var(--el-text);
    }
    .ext-lp-hero-hub {
      margin: 0.35rem 0 0;
      font-size: 0.7rem;
      font-weight: 700;
      letter-spacing: 0.32em;
      text-transform: uppercase;
      color: var(--el-muted);
    }
    .ext-lp-hero-edition {
      margin: 0.45rem 0 0;
      font-size: 0.62rem;
      font-weight: 800;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      color: #c62828;
    }
    .ext-lp-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.65rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--el-gm);
      margin-bottom: 12px;
      padding: 5px 11px;
      background: var(--el-card);
      border-radius: 999px;
      border: 1px solid var(--el-bd);
    }
    .ext-lp-hero h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.75rem, 4.5vw, 2.35rem);
      font-weight: 800;
      letter-spacing: -0.035em;
      line-height: 1.12;
      min-height: 2.65em;
    }
    .ext-lp-lead {
      max-width: 34rem;
      margin: 0 auto 1.1rem;
      color: var(--el-muted);
      font-size: 1.02rem;
    }
    .ext-lp-hero-act { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; align-items: center; }
    .ext-lp-ghost {
      display: inline-flex;
      padding: 0.62rem 1.15rem;
      border-radius: 999px;
      font-weight: 600;
      font-size: 0.85rem;
      text-decoration: none;
      color: var(--el-gm);
      border: 2px solid var(--el-bd);
      background: transparent;
    }
    .ext-lp-ghost:hover { background: var(--el-bds); }
    .ext-lp-trust {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 8px 14px;
      margin-bottom: 1.75rem;
      font-size: 0.76rem;
      font-weight: 600;
      color: var(--el-muted);
    }
    .ext-lp-trust span {
      padding: 5px 11px;
      background: var(--el-card);
      border-radius: 999px;
      border: 1px solid var(--el-bd);
    }
    .ext-lp-sh {
      display: flex;
      flex-wrap: nowrap;
      align-items: center;
      justify-content: space-between;
      gap: 12px 16px;
      margin-bottom: 16px;
    }
    .ext-lp-sh h2 {
      margin: 0;
      font-size: 1.25rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      line-height: 1.25;
      flex: 1 1 auto;
      min-width: 0;
    }
    .ext-lp-sh p {
      margin: 0;
      font-size: 0.88rem;
      color: var(--el-muted);
      flex: 0 0 auto;
      white-space: nowrap;
    }
    .ext-lp-grid {
      display: grid;
      gap: 1.25rem;
      grid-template-columns: 1fr;
      min-height: 280px;
      contain: layout style;
    }
    @media (min-width: 560px) {
      .ext-lp-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
    @media (min-width: 900px) {
      .ext-lp-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    }
    /* Catalog grid is on #amo-catalog-root.ext-lp-grid (articles are direct grid children). */
    .ext-lp-card {
      background: var(--el-card);
      border-radius: var(--radius);
      border: 1px solid var(--el-bd);
      box-shadow: var(--el-sh);
      padding: 1.25rem;
      display: flex;
      flex-direction: column;
      transition: transform 0.22s ease, box-shadow 0.22s, border-color 0.2s;
    }
    .ext-lp-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--el-shh);
      border-color: var(--el-gb);
    }
    .ext-lp-card.ext-lp-feat {
      grid-column: 1 / -1;
      flex-direction: row;
      flex-wrap: wrap;
      gap: 16px;
      padding: 1.35rem;
    }
    @media (max-width: 640px) {
      .ext-lp-card.ext-lp-feat { flex-direction: column; }
    }
    .ext-lp-top { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 8px; }
    .ext-lp-ic {
      width: 52px;
      height: 52px;
      border-radius: 15px;
      background: linear-gradient(145deg, #e8f5e9, #c8e6c9);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.45rem;
      flex-shrink: 0;
    }
    .ext-lp-ic.ext-lp-ic-pic {
      padding: 2px;
      background: #fff;
      border: 1px solid var(--el-bds);
      box-sizing: border-box;
    }
    .ext-lp-ic img.ext-lp-ic-img {
      width: 100%;
      height: 100%;
      border-radius: 12px;
      object-fit: contain;
      display: block;
    }
    .ext-lp-card h2 {
      margin: 0 0 3px;
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--el-text);
    }
    .ext-lp-tag {
      font-size: 0.65rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.07em;
      color: var(--el-gm);
      margin-bottom: 4px;
    }
    .ext-lp-meta { font-size: 0.76rem; color: var(--el-muted); margin-bottom: 8px; }
    .ext-lp-card > p { margin: 0 0 12px; font-size: 0.9rem; color: var(--el-muted); flex: 1; }
    .ext-lp-act { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
    .ext-lp-ls {
      font-size: 0.8rem;
      font-weight: 600;
      color: var(--el-gm);
      text-decoration: none;
      border-bottom: 1px solid transparent;
    }
    .ext-lp-ls:hover { border-bottom-color: var(--el-gm); }
    .ext-lp-root a.btn-firefox {
      background: linear-gradient(135deg, #ff7139, #e25500) !important;
      color: #fff !important;
      border: 1px solid #c2410c !important;
      box-shadow: 0 3px 14px rgba(226, 85, 0, 0.35) !important;
    }
    .ext-lp-root a.btn-firefox:hover { filter: brightness(1.06); }
    .ext-lp-foot-note { text-align: center; font-size: 0.82rem; color: var(--el-muted); margin: 1.25rem 0 0; }
    header.ext-lp-topbar {
      border-radius: 14px;
      border: 1px solid var(--el-bds);
      max-width: 1080px;
      margin-left: auto;
      margin-right: auto;
      width: calc(100% - 32px);
      box-shadow: var(--el-sh);
    }
    article.card.platform-tile { position: relative; overflow: hidden; }
    article.card.platform-tile::before {
      content: "";
      position: absolute;
      left: 0;
      right: 0;
      top: 0;
      height: 3px;
      background: linear-gradient(90deg, #ff7139, var(--el-gm));
      opacity: 0.65;
      pointer-events: none;
    }
    .listing-hint {
      font-size: 0.7rem;
      font-weight: 800;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      color: var(--muted);
      margin: 0 0 12px;
    }

    /* ============ EXTENSIONS: animations + new components (theme-variable only, AMP-safe) ============ */
    @keyframes wlFadeUp {
      from { opacity: 0; transform: translateY(18px); }
      to { opacity: 1; transform: none; }
    }
    @keyframes wlZoomIn {
      from { opacity: 0; transform: scale(0.86); }
      to { opacity: 1; transform: scale(1); }
    }
    @keyframes wlShimmer {
      0% { background-position: 130% 0; }
      100% { background-position: -30% 0; }
    }
    @keyframes wlFoxWiggle {
      0%, 100% { transform: rotate(0); }
      25% { transform: rotate(-9deg); }
      75% { transform: rotate(9deg); }
    }
    @keyframes wlShine {
      from { left: -80%; }
      to { left: 130%; }
    }
    @keyframes wlPopIn {
      from { opacity: 0; transform: scale(0.6) translateY(10px); }
      to { opacity: 1; transform: scale(1) translateY(0); }
    }
    /* Hero entrance cascade (homepage) */
    .ext-lp-hero-logo-wrap { animation: wlZoomIn 0.55s cubic-bezier(0.22, 1, 0.36, 1) both; }
    .ext-lp-badge { animation: wlFadeUp 0.5s ease-out 0.1s both; }
    .ext-lp-hero h1 { animation: wlFadeUp 0.55s ease-out 0.18s both; }
    .ext-lp-lead { animation: wlFadeUp 0.55s ease-out 0.28s both; }
    .ext-lp-hero-act { animation: wlFadeUp 0.55s ease-out 0.38s both; }
    .ext-lp-trust { animation: wlFadeUp 0.5s ease-out 0.5s both; }
    /* Scroll reveal (IntersectionObserver adds .wl-in) */
    .wl-reveal {
      opacity: 0;
      transform: translateY(18px);
      transition: opacity 0.5s ease-out, transform 0.55s cubic-bezier(0.22, 1, 0.36, 1);
    }
    .wl-reveal.wl-in { opacity: 1; transform: none; }
    /* Skeleton shimmer while the AMO catalog loads */
    .ext-lp-skel {
      pointer-events: none;
      min-height: 190px;
      border: 1px dashed var(--el-bd);
      background-image: linear-gradient(100deg, transparent 25%, rgba(120, 144, 126, 0.14) 42%, transparent 58%);
      background-size: 220% 100%;
      background-repeat: no-repeat;
      background-position: 130% 0;
      animation: wlShimmer 1.3s linear infinite;
    }
    /* Micro-interactions */
    a.btn-firefox {
      position: relative;
      overflow: hidden;
      isolation: isolate;
    }
    a.btn-firefox:hover .fox-icon,
    a.btn-firefox:focus-visible .fox-icon { display: inline-block; animation: wlFoxWiggle 0.5s ease-in-out; }
    a.btn-firefox::after {
      content: "";
      position: absolute;
      top: 0;
      bottom: 0;
      left: -80%;
      width: 45%;
      transform: skewX(-22deg);
      background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);
      pointer-events: none;
    }
    a.btn-firefox:hover::after { animation: wlShine 0.85s ease; }
    .topbar-logo { transition: transform 0.25s ease, box-shadow 0.25s ease; }
    .topbar-brand:hover .topbar-logo { transform: scale(1.06) rotate(-2deg); }
    .topbar.scrolled { box-shadow: 0 6px 22px rgba(10, 10, 10, 0.1); }
    /* Theme toggle button (light/dark) */
    .theme-toggle {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-width: 44px;
      min-height: 44px;
      padding: 6px;
      font-size: 1.1rem;
      line-height: 1;
      color: var(--text);
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: 12px;
      cursor: pointer;
      transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
    }
    .theme-toggle:hover { border-color: var(--green-bright); transform: translateY(-1px) scale(1.05); }
    .theme-toggle:focus-visible { outline: 2px solid var(--green-mid); outline-offset: 2px; }
    .theme-toggle .tt-light { display: none; }
    html.theme-dark .theme-toggle .tt-light { display: inline; }
    html.theme-dark .theme-toggle .tt-dark { display: none; }
    /* Back to top */
    .back-to-top {
      position: fixed;
      right: 18px;
      bottom: 18px;
      z-index: 60;
      width: 46px;
      height: 46px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.15rem;
      color: #fff;
      background: linear-gradient(135deg, var(--el-g), var(--el-gm));
      border: 1px solid var(--el-bd);
      border-radius: 999px;
      text-decoration: none;
      box-shadow: 0 8px 24px rgba(27, 94, 32, 0.35);
      opacity: 0;
      visibility: hidden;
      transform: translateY(12px);
      transition: opacity 0.25s ease, transform 0.25s ease, visibility 0.25s;
    }
    .back-to-top.show { opacity: 1; visibility: visible; transform: none; animation: wlPopIn 0.3s ease; }
    .back-to-top:hover { transform: translateY(-3px); }
    .back-to-top:focus-visible { outline: 2px solid var(--green-bright); outline-offset: 2px; }
    /* Mobile nav (burger) */
    .nav-burger {
      display: none;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 4px;
      min-width: 44px;
      min-height: 44px;
      background: transparent;
      border: 1px solid var(--border);
      border-radius: 12px;
      cursor: pointer;
      padding: 0;
    }
    .nav-burger span {
      display: block;
      width: 18px;
      height: 2px;
      border-radius: 2px;
      background: var(--text);
      transition: transform 0.25s ease, opacity 0.2s ease;
    }
    body.nav-open .nav-burger span:nth-child(1) { transform: translateY(6px) rotate(45deg); }
    body.nav-open .nav-burger span:nth-child(2) { opacity: 0; }
    body.nav-open .nav-burger span:nth-child(3) { transform: translateY(-6px) rotate(-45deg); }
    @media (max-width: 820px) {
      .nav-burger { display: inline-flex; }
      .topbar-nav {
        position: absolute;
        top: calc(var(--topbar-h) + 8px);
        right: 12px;
        left: 12px;
        flex-direction: column;
        align-items: stretch;
        gap: 4px;
        padding: 10px;
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: 16px;
        box-shadow: var(--shadow-hover);
        opacity: 0;
        visibility: hidden;
        transform: translateY(-8px);
        transition: opacity 0.22s ease, transform 0.22s ease, visibility 0.22s;
      }
      body.nav-open .topbar-nav { opacity: 1; visibility: visible; transform: none; }
      .topbar-nav a { justify-content: flex-start; width: 100%; }
    }
    /* FAQ smooth open/close */
    .faq details ::details-content { display: contents; }
    .faq details p {
      opacity: 0;
      transform: translateY(-4px);
      transition: opacity 0.3s ease, transform 0.3s ease;
    }
    .faq details[open] p { opacity: 1; transform: none; }
    @supports (interpolate-size: allow-keywords) {
      .faq details { interpolate-size: allow-keywords; }
      .faq details::details-content {
        height: 0;
        overflow: hidden;
        transition: height 0.32s ease, content-visibility 0.32s allow-discrete;
      }
      .faq details[open]::details-content { height: auto; }
    }
    /* Share buttons */
    .share-row {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 8px;
      margin-top: 18px;
      padding-top: 16px;
      border-top: 1px solid var(--border-soft);
    }
    .share-row .share-label { font-size: 0.78rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
    .share-row a, .share-row button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-width: 44px;
      min-height: 44px;
      padding: 6px 12px;
      font-size: 0.8rem;
      font-weight: 700;
      font-family: inherit;
      text-decoration: none;
      color: var(--text);
      background: var(--border-soft);
      border: 1px solid var(--border);
      border-radius: 999px;
      cursor: pointer;
      transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
    }
    .share-row a:hover, .share-row button:hover { transform: translateY(-2px); border-color: var(--green-bright); box-shadow: 0 6px 16px rgba(27, 94, 32, 0.16); }
    /* Related posts */
    .related-box { margin-top: 26px; padding: 22px 24px; background: var(--card); border-radius: var(--radius); border: 1px solid var(--border); box-shadow: var(--shadow); }
    .related-box h3 { margin: 0 0 14px; font-size: 1.05rem; font-weight: 800; }
    .related-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
    .related-list a {
      display: flex;
      align-items: center;
      min-height: 44px;
      padding: 10px 12px;
      border-radius: 10px;
      background: var(--border-soft);
      border: 1px solid var(--border);
      color: var(--text);
      font-weight: 600;
      font-size: 0.88rem;
      text-decoration: none !important;
      transition: border-color 0.2s ease, transform 0.2s ease;
    }
    .related-list a:hover { border-color: var(--green-bright); transform: translateX(3px); }

    /* ============ EXTENSIONS: professional polish pack ============ */
    /* Animated gradient headline (hero) */
    @keyframes wlGradientShift {
      0% { background-position: 0% 50%; }
      50% { background-position: 100% 50%; }
      100% { background-position: 0% 50%; }
    }
    .ext-lp-hero h1 {
      background: linear-gradient(90deg, var(--green-mid), var(--green-bright), var(--firefox), var(--green-mid));
      background-size: 250% 100%;
      -webkit-background-clip: text;
      background-clip: text;
      -webkit-text-fill-color: transparent;
      color: transparent;
      animation: wlFadeUp 0.55s ease-out 0.18s both, wlGradientShift 7s ease-in-out 0.9s infinite;
    }
    /* Floating hero logo */
    @keyframes wlFloat {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-6px); }
    }
    .ext-lp-hero-logo { animation: wlFloat 5s ease-in-out 1.2s infinite; }
    /* Badge shimmer sweep */
    @keyframes wlBadgeShine {
      0% { background-position: -150% 0; }
      60%, 100% { background-position: 250% 0; }
    }
    .ext-lp-badge { position: relative; overflow: hidden; }
    .ext-lp-badge::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(110deg, transparent 32%, rgba(255, 255, 255, 0.45) 50%, transparent 68%);
      background-size: 200% 100%;
      background-repeat: no-repeat;
      animation: wlBadgeShine 3.6s ease-in-out 1.4s infinite;
      pointer-events: none;
    }
    /* Nav link animated underline */
    .topbar-nav a { position: relative; }
    .topbar-nav a::after {
      content: "";
      position: absolute;
      left: 14px;
      right: 14px;
      bottom: 7px;
      height: 2px;
      border-radius: 2px;
      background: var(--green-mid);
      transform: scaleX(0);
      transform-origin: left center;
      transition: transform 0.25s ease;
      pointer-events: none;
    }
    .topbar-nav a:hover::after,
    .topbar-nav a:focus-visible::after { transform: scaleX(1); }
    /* Topbar shrink on scroll */
    .topbar { transition: height 0.25s ease, box-shadow 0.25s ease; }
    .topbar.topbar-shrink { height: calc(var(--topbar-h) - 12px); }
    .topbar-logo {
      transition: transform 0.25s ease, box-shadow 0.25s ease, width 0.25s ease, height 0.25s ease;
    }
    .topbar.topbar-shrink .topbar-logo { width: 34px; height: 34px; }
    /* Ambient glow orb (decorative) */
    @keyframes wlGlowDrift {
      0%, 100% { transform: translate(0, 0) scale(1); opacity: 0.55; }
      50% { transform: translate(28px, -22px) scale(1.08); opacity: 0.8; }
    }
    body::after {
      content: "";
      position: fixed;
      top: 12%;
      right: -12%;
      width: 440px;
      height: 440px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(67, 160, 71, 0.10), transparent 70%);
      pointer-events: none;
      z-index: 0;
      animation: wlGlowDrift 13s ease-in-out infinite;
    }
    /* Card 3D tilt (JS adds transform on pointermove) */
    .grid, .ext-lp-grid { perspective: 1200px; }
    .card.wl-tilt, .ext-lp-card.wl-tilt {
      transform-style: preserve-3d;
      will-change: transform;
      transition: transform 0.14s ease-out, box-shadow 0.25s ease, border-color 0.2s;
    }

    /* ============ EXTENSIONS: live data pack (Firefox badge, stars, stats pop, GitHub cards) ============ */
    .wl-ff-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      margin-top: 12px;
      padding: 7px 14px;
      font-size: 0.82rem;
      font-weight: 600;
      color: var(--el-text);
      background: var(--el-card);
      border: 1px solid var(--el-bd);
      border-radius: 999px;
      box-shadow: var(--el-sh);
      animation: wlFadeUp 0.5s ease-out 0.35s both;
    }
    .wl-ff-badge strong { color: var(--el-gm); font-weight: 800; }
    .wl-stars { margin-top: 4px; font-size: 0.82rem; font-weight: 700; color: var(--firefox); }
    .wl-stars span { letter-spacing: 1px; }
    .stats-strip .stat strong.wl-pop { animation: wlPopIn 0.45s ease-out both; }
    .wl-gh-row { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 18px 0 0; }
    .wl-gh-card {
      display: flex;
      flex-direction: column;
      gap: 2px;
      min-width: 190px;
      padding: 12px 16px;
      background: var(--el-card);
      border: 1px solid var(--el-bd);
      border-radius: var(--radius);
      color: var(--el-text);
      text-decoration: none !important;
      font-size: 0.82rem;
      transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
      animation: wlFadeUp 0.5s ease-out both;
    }
    .wl-gh-card:hover { transform: translateY(-3px); border-color: var(--el-gb); box-shadow: var(--el-shh); }
    .wl-gh-card strong { font-size: 0.92rem; color: var(--el-text); }
    .wl-gh-card em { color: var(--el-gm); font-style: normal; }

    /* Reduced motion: everything appears instantly (also set by JS on body) */
    body.wl-reduced-motion *,
    body.wl-reduced-motion *::before,
    body.wl-reduced-motion *::after {
      animation: none !important;
      transition: none !important;
    }
    body.wl-reduced-motion .wl-reveal { opacity: 1; transform: none; }

div.script:
//
window.__AMO_CATALOG__ = window.__AMO_CATALOG__ || { author: '19705561', exclude: '' };
/**
 * Live Firefox add-on catalog from AMO (no theme re-upload).
 * Paste into Blogger theme once, or load as external script if your host allows.
 *
 * Config: window.__AMO_CATALOG__ = { author: "19705561", exclude: "slug1,slug2" };
 * Defaults: author 19705561, exclude empty.
 */
(function () {
  "use strict";

  var CFG = window.__AMO_CATALOG__ || {};
  var AUTHOR = String(CFG.author || "19705561");
  var EXCLUDE = {};
  String(CFG.exclude || "")
    .split(/[,\s]+/)
    .forEach(function (s) {
      s = s.trim().toLowerCase();
      if (s) EXCLUDE[s] = true;
    });

  function addonTitle(a) {
    var n = a.name;
    if (n && typeof n === "object") {
      return n["en-US"] || Object.keys(n).map(function (k) { return n[k]; })[0] || a.slug || "?";
    }
    return String(n || a.slug || "?");
  }

  function addonSummary(a) {
    var s = a.summary;
    var t = "";
    if (s && typeof s === "object") {
      t = s["en-US"] || Object.keys(s).map(function (k) { return s[k]; })[0] || "";
    } else {
      t = String(s || "");
    }
    t = t.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
    if (t.length > 240) t = t.slice(0, 237) + "...";
    return t || "Firefox WebExtension on Mozilla AMO.";
  }

  function slugIcon(slug) {
    var sl = (slug || "").toLowerCase();
    if (sl.indexOf("youtube") >= 0) return "\u25b6\ufe0f";
    if (sl.indexOf("password") >= 0 || sl.indexOf("generator") >= 0) return "\ud83d\udd10";
    if (sl.indexOf("phish") >= 0) return "\ud83d\udee1\ufe0f";
    if (sl.indexOf("tarjam") >= 0 || sl.indexOf("translat") >= 0) return "\ud83c\udf10";
    if (sl.indexOf("aegis") >= 0) return "\ud83d\udd12";
    return "\ud83e\udde9";
  }

  function slugTag(slug) {
    var sl = (slug || "").toLowerCase();
    if (sl.indexOf("youtube") >= 0) return "Featured \u00b7 YouTube";
    if (sl.indexOf("password") >= 0 || sl.indexOf("generator") >= 0) return "Passwords";
    if (sl.indexOf("phish") >= 0) return "Security";
    if (sl.indexOf("tarjam") >= 0) return "Translation";
    if (sl.indexOf("aegis") >= 0) return "Privacy";
    return "Firefox \u00b7 AMO";
  }

  function addonTagLine(a) {
    var slug = String(a.slug || "");
    var cur = slugTag(slug);
    if (cur !== "Firefox \u00b7 AMO") return cur;
    var cats = a.categories;
    if (cats && cats.length) {
      return String(cats[0])
        .split("-")
        .map(function (w) {
          return w ? w.charAt(0).toUpperCase() + w.slice(1).toLowerCase() : "";
        })
        .join(" ");
    }
    return "Firefox \u00b7 AMO";
  }

  function formatUsers(n) {
    if (n < 0) n = 0;
    if (n >= 1e6) {
      var m = (n / 1e6).toFixed(1).replace(/\.0$/, "");
      return m + "M users";
    }
    if (n >= 1e3) {
      var k = (n / 1e3).toFixed(1).replace(/\.0$/, "");
      return k + "k users";
    }
    return n + " users";
  }

  function addonMetaLine(a) {
    var parts = [];
    var u = a.average_daily_users;
    if (typeof u === "number" && u > 0) parts.push(formatUsers(u));
    var r = a.ratings || {};
    var cnt = r.count || 0;
    if (cnt > 0) {
      var avg = Number(r.average) || 0;
      parts.push(avg.toFixed(1) + " (" + String(cnt) + " reviews)");
    }
    parts.push("AMO");
    return parts.join(" \u00b7 ");
  }

  function starsHtml(a) {
    var r = a.ratings || {};
    var cnt = r.count || 0;
    if (cnt <= 0) return "";
    var avg = Number(r.average) || 0;
    var full = Math.max(0, Math.min(5, Math.round(avg)));
    var s = "";
    for (var i = 1; i <= 5; i++) s += i <= full ? "\u2605" : "\u2606";
    return (
      "<div class='wl-stars' role='img' aria-label='" + avg.toFixed(1) + " out of 5 stars (" + cnt + " reviews)'>" +
      "<span aria-hidden='true'>" + s + "</span> " + avg.toFixed(1) + "</div>"
    );
  }

  function addonIconUrl(a) {
    var icons = a.icons || {};
    var order = ["64", "32", "128"];
    for (var i = 0; i < order.length; i++) {
      var u = icons[order[i]];
      if (typeof u === "string" && u.indexOf("http") === 0 && u.indexOf("/default-") < 0) return u;
    }
    var iu = a.icon_url;
    if (typeof iu === "string" && iu.indexOf("http") === 0 && iu.indexOf("default-128") < 0 && iu.indexOf("/default-") < 0) {
      return iu;
    }
    return null;
  }

  function iconUrlForDisplay(u) {
    if (typeof u !== "string" || !u) return u;
    if (u.indexOf("-128.png") !== -1) return u.replace(/-128\.png/g, "-64.png");
    if (u.indexOf("_128.png") !== -1) return u.replace(/_128\.png/g, "_64.png");
    return u;
  }

  function esc(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function hrefEsc(url) {
    return esc(url || "").replace(/'/g, "&#39;");
  }

  function featuredIndex(addons) {
    for (var i = 0; i < addons.length; i++) {
      if ((addons[i].slug || "").toLowerCase().indexOf("youtube") >= 0) return i;
    }
    return 0;
  }

  function orderAddons(addons) {
    var fi = featuredIndex(addons);
    var first = addons[fi];
    var rest = [];
    for (var i = 0; i < addons.length; i++) {
      if (i !== fi) rest.push(addons[i]);
    }
    return [first].concat(rest);
  }

  async function fetchAll() {
    var results = [];
    var url = "https://addons.mozilla.org/api/v5/addons/search/?author=" + encodeURIComponent(AUTHOR) + "&type=extension&page_size=50";
    while (url) {
      var res = await fetch(url, { credentials: "omit" });
      if (!res.ok) throw new Error("AMO " + res.status);
      var data = await res.json();
      var batch = data.results || [];
      for (var i = 0; i < batch.length; i++) results.push(batch[i]);
      url = data.next || null;
    }
    results.sort(function (a, b) {
      return addonTitle(a).toLowerCase().localeCompare(addonTitle(b).toLowerCase());
    });
    return results.filter(function (a) {
      var sl = (a.slug || "").toLowerCase();
      return !EXCLUDE[sl];
    });
  }

  function cardHtml(a, featured) {
    var title = esc(addonTitle(a));
    var url = hrefEsc(a.url || "");
    var summ = esc(addonSummary(a));
    var tag = esc(addonTagLine(a));
    var meta = esc(addonMetaLine(a));
    var stars = starsHtml(a);
    var slug = String(a.slug || "");
    var icUrl = iconUrlForDisplay(addonIconUrl(a));
    var iconBlock;
    if (icUrl) {
      iconBlock =
        "<div class='ext-lp-ic ext-lp-ic-pic' aria-hidden='true'><img class='ext-lp-ic-img' src='" +
        hrefEsc(icUrl) +
        "' alt='' width='52' height='52' sizes='52px' loading='lazy' decoding='async' fetchpriority='low'/></div>";
    } else {
      iconBlock = "<div class='ext-lp-ic' aria-hidden='true'>" + slugIcon(slug) + "</div>";
    }
    var featCls = featured ? " ext-lp-feat" : "";
    var inner =
      "                <article class='ext-lp-card" +
      featCls +
      "'>\n                  <div class='ext-lp-top'>\n" +
      "                    " +
      iconBlock +
      "\n                    <div>\n                      <div class='ext-lp-tag'>" +
      tag +
      "</div>\n                      <h2>" +
      title +
      "</h2>\n                      <div class='ext-lp-meta'>" +
      meta +
      "</div>" +
      stars +
      "\n                    </div>\n                  </div>\n";
    if (featured) {
      inner +=
        "                  <div style='flex:1;min-width:220px'>\n                    <p>" +
        summ +
        "</p>\n                    <div class='ext-lp-act'>\n                      <a class='btn-firefox' href='" +
        url +
        "' rel='noopener noreferrer' target='_blank'>\n                        <span class='fox-icon' aria-hidden='true'>\ud83e\udd8a</span>\n                        Firefox \u2014 install\n                      </a>\n                      <a class='ext-lp-ls' href='" +
        url +
        "' rel='noopener noreferrer' target='_blank'>AMO page \u2192</a>\n                    </div>\n                  </div>\n";
    } else {
      inner +=
        "                  <p>" +
        summ +
        "</p>\n                  <div class='ext-lp-act'>\n                    <a class='btn-firefox' href='" +
        url +
        "' rel='noopener noreferrer' target='_blank'>\n                      <span class='fox-icon' aria-hidden='true'>\ud83e\udd8a</span>\n                      Firefox \u2014 install\n                    </a>\n                  </div>\n";
    }
    inner += "                </article>";
    return inner;
  }

  function injectItemListJsonLd(addons) {
    var el = document.getElementById("amo-itemlist-ld");
    if (!el) return;
    var items = addons.map(function (a, i) {
      var app = {
        "@type": "SoftwareApplication",
        name: addonTitle(a),
        url: a.url || "",
        operatingSystem: "Firefox",
        applicationCategory: "BrowserApplication",
      };
      var r = a.ratings || {};
      if ((r.count || 0) > 0) {
        app.aggregateRating = {
          "@type": "AggregateRating",
          ratingValue: Number(r.average) || 0,
          ratingCount: r.count,
          bestRating: 5,
          worstRating: 1,
        };
      }
      if (typeof a.average_daily_users === "number" && a.average_daily_users > 0) {
        app.interactionStatistic = {
          "@type": "InteractionCounter",
          interactionType: "https://schema.org/InstallAction",
          userInteractionCount: a.average_daily_users,
        };
      }
      return {
        "@type": "ListItem",
        position: i + 1,
        item: app,
      };
    });
    el.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "ItemList",
      "name": "Featured Firefox add-ons (AMO)",
      "numberOfItems": items.length,
      "itemListElement": items,
    });
  }
  
  function renderSkeleton() {
    var html = "";
    for (var i = 0; i < 3; i++) {
      html += "<article class='ext-lp-card ext-lp-skel' aria-hidden='true'></article>";
    }
    html += "<p class='ext-lp-meta' id='amo-loading-msg'>Loading catalog from Mozilla AMO\u2026</p>";
    return html;
  }
  
  function staggerReveal(root) {
    var cards = root.querySelectorAll(".ext-lp-card");
    for (var i = 0; i < cards.length; i++) {
      cards[i].style.animation = "wlFadeUp 0.5s ease-out both";
      cards[i].style.animationDelay = Math.min(i * 70, 420) + "ms";
    }
  }
  
  var CACHE_KEY = "amoCatalogV1";
  var CACHE_TTL = 10 * 60 * 1000;
  
  function readCache() {
    try {
      var raw = window.sessionStorage.getItem(CACHE_KEY);
      if (!raw) return null;
      var obj = JSON.parse(raw);
      if (!obj || typeof obj.t !== "number" || !obj.items) return null;
      return obj;
    } catch (e) {
      return null;
    }
  }
  
  function writeCache(items) {
    try {
      window.sessionStorage.setItem(CACHE_KEY, JSON.stringify({ t: Date.now(), items: items }));
    } catch (e) {}
  }
  
  function updateLiveStats(addons) {
    var totalUsers = 0;
    for (var i = 0; i < addons.length; i++) {
      var u = addons[i].average_daily_users;
      if (typeof u === "number" && u > 0) totalUsers += u;
    }
    var set = function (id, text) {
      var el = document.getElementById(id);
      if (el && text) {
        el.textContent = text;
        el.classList.remove("wl-pop");
        void el.offsetWidth;
        el.classList.add("wl-pop");
      }
    };
    set("statAddons", String(addons.length));
    set("statUsers", formatUsers(totalUsers).replace(" users", ""));
  }

  function renderCatalog(root, addons) {
    var ordered = orderAddons(addons);
    root.innerHTML = ordered
      .map(function (a, i) {
        return cardHtml(a, i === 0);
      })
      .join("\n");
    injectItemListJsonLd(ordered);
    updateLiveStats(ordered);
    staggerReveal(root);
  }
  
  function renderError(root) {
    root.innerHTML =
      "<p class='ext-lp-meta'>Catalog could not load. <a class='ext-lp-ls' href='https://addons.mozilla.org/en-US/firefox/user/" +
      esc(AUTHOR) +
      "/' rel='noopener noreferrer' target='_blank'>Open AMO profile \u2192</a></p>";
  }
  
  function run() {
    var root = document.getElementById("amo-catalog-root");
    if (!root) return;
    var cached = readCache();
    if (cached && cached.items.length && Date.now() - cached.t < CACHE_TTL) {
      renderCatalog(root, cached.items);
      return;
    }
    if (cached && cached.items.length) {
      renderCatalog(root, cached.items);
    } else {
      root.innerHTML = renderSkeleton();
    }
    fetchAll()
      .then(function (addons) {
        if (!addons.length) {
          root.innerHTML =
            "<p class='ext-lp-meta'>No add-ons found on AMO for this author.</p>";
          return;
        }
        writeCache(addons);
        renderCatalog(root, addons);
      })
      .catch(function (e) {
        if (cached && cached.items.length) return;
        renderError(root);
        if (window.console && console.warn) console.warn("[amo-catalog]", e);
      });
  }

  function scheduleCatalog() {
    var started = false;
    var kick = function () {
      if (started) return;
      started = true;
      run();
    };
    /* rAF defers to next paint; hidden tabs / headless renderers (Googlebot) never
       fire rAF, so fall back to a timer and re-kick on visibilitychange. */
    var defer = function () {
      if (started) return;
      if (window.requestAnimationFrame && document.visibilityState !== "hidden") {
        requestAnimationFrame(function () {
          requestAnimationFrame(kick);
        });
      } else {
        setTimeout(kick, 60);
      }
    };
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", defer);
    } else {
      defer();
    }
    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "visible") defer();
    });
    setTimeout(kick, 2500); /* safety net: background tabs / headless renderers */
  }
  scheduleCatalog();
})();

