//
/* CONFIG GitHub: ila bghiti t-warr repos dyal extensions dyalek, zid hna "owner/repo".
   Khallih vide ([]) ila ma 3andekch repos — section kat-khba rasha automatiquement. */
window.__WL_GITHUB__ = window.__WL_GITHUB__ || { repos: [] };
/**
 * Live data pack:
 * 1) Firefox versions (product-details.mozilla.org) -> hero badge + stats strip (fresh content / SEO)
 * 2) GitHub repos (optional, config-driven) -> stars / forks / last-update cards
 */
(function () {
  "use strict";

  var FF_KEY = "wlFxVersionsV1";
  var FF_TTL = 6 * 60 * 60 * 1000;

  function fmtDate(iso) {
    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    var p = String(iso || "").split("-");
    if (p.length !== 3) return String(iso || "");
    var m = parseInt(p[1], 10);
    var day = parseInt(p[2], 10);
    if (!m || !day || m < 1 || m > 12) return String(iso);
    return months[m - 1] + " " + day;
  }

  function fillFf(v) {
    if (!v) return;
    var ver = v.LATEST_FIREFOX_VERSION || "";
    var badge = document.querySelector(".wl-ff-badge");
    var verEl = document.getElementById("ffVersion");
    var statVer = document.getElementById("statFfVersion");
    var statNext = document.getElementById("statNextRelease");
    if (ver) {
      if (verEl) verEl.textContent = ver;
      if (badge) badge.hidden = false;
      if (statVer) statVer.textContent = ver;
    }
    if (statNext && v.NEXT_RELEASE_DATE) statNext.textContent = fmtDate(v.NEXT_RELEASE_DATE);
  }

  function loadFirefoxVersions() {
    var cached = null;
    try {
      var raw = window.sessionStorage.getItem(FF_KEY);
      if (raw) cached = JSON.parse(raw);
    } catch (e) { cached = null; }
    if (cached && cached.t && cached.v && Date.now() - cached.t < FF_TTL) {
      fillFf(cached.v);
      return;
    }
    fetch("https://product-details.mozilla.org/1.0/firefox_versions.json", { credentials: "omit" })
      .then(function (res) {
        if (!res.ok) throw new Error("product-details " + res.status);
        return res.json();
      })
      .then(function (v) {
        try { window.sessionStorage.setItem(FF_KEY, JSON.stringify({ t: Date.now(), v: v })); } catch (e) {}
        fillFf(v);
      })
      .catch(function () { /* silent: badge stays hidden */ });
  }

  function escAttr(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function loadGitHub() {
    var cfg = window.__WL_GITHUB__ || {};
    var repos = (cfg.repos || []).slice(0, 4);
    var row = document.getElementById("ghRow");
    if (!row || !repos.length) return;
    Promise.all(repos.map(function (full) {
      return fetch("https://api.github.com/repos/" + encodeURIComponent(full), { credentials: "omit" })
        .then(function (res) { return res.ok ? res.json() : null; })
        .catch(function () { return null; });
    })).then(function (list) {
      var cards = [];
      for (var i = 0; i < list.length; i++) {
        var repo = list[i];
        if (!repo) continue;
        cards.push(
          "<a class='wl-gh-card' href='" + escAttr(repo.html_url) + "' rel='noopener noreferrer' target='_blank' style='animation-delay:" + (i * 90) + "ms'>" +
          "<strong>" + escAttr(repo.name || "") + "</strong>" +
          "<span>\u2b50 " + (repo.stargazers_count || 0) + " \u00b7 \ud83c\udf74 " + (repo.forks_count || 0) + "</span>" +
          "<em>updated " + escAttr(String(repo.pushed_at || "").slice(0, 10)) + "</em></a>"
        );
      }
      if (cards.length) {
        row.innerHTML = cards.join("");
        row.hidden = false;
      }
    });
  }

  function run() {
    loadFirefoxVersions();
    loadGitHub();
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", run);
  } else {
    run();
  }
})();
