footer.script:
//
(function () {
  "use strict";
  var d = document, de = d.documentElement;

  /* Reduced motion flag (mirrors the CSS media query for JS-driven animation) */
  if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    d.body.classList.add("wl-reduced-motion");
  }

  /* Manual dark/light toggle: overrides prefers-color-scheme, persists in localStorage */
  function applyTheme(m) {
    de.classList.toggle("theme-dark", m === "dark");
    de.style.colorScheme = m;
  }
  var stored = null;
  try { stored = window.localStorage.getItem("wl-theme"); } catch (e) {}
  if (stored === "dark" || stored === "light") applyTheme(stored);
  var tt = d.getElementById("themeToggle");
  if (tt) {
    tt.addEventListener("click", function () {
      var dark = de.classList.toggle("theme-dark");
      de.style.colorScheme = dark ? "dark" : "light";
      try { window.localStorage.setItem("wl-theme", dark ? "dark" : "light"); } catch (e) {}
    });
  }

  /* Reading progress bar (drives .lp-readbar width) */
  var bar = d.querySelector(".lp-readbar");
  function updateBar() {
    if (!bar) return;
    var h = de.scrollHeight - window.innerHeight;
    var p = h > 0 ? Math.min(100, Math.max(0, (window.scrollY / h) * 100)) : 100;
    bar.style.width = p + "%";
    bar.style.right = "auto";
  }

  /* Back to top visibility + topbar shadow */
  var btt = d.getElementById("backToTop");
  var topbar = d.querySelector(".topbar");
  function onScroll() {
    updateBar();
    if (btt) btt.classList.toggle("show", window.scrollY > 600);
    if (topbar) topbar.classList.toggle("scrolled", window.scrollY > 8);
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();
  if (btt) {
    btt.addEventListener("click", function (e) {
      e.preventDefault();
      window.scrollTo({ top: 0, behavior: d.body.classList.contains("wl-reduced-motion") ? "auto" : "smooth" });
    });
  }

  /* Mobile nav burger */
  var burger = d.getElementById("navBurger");
  var nav = d.getElementById("topbar-nav");
  if (burger && nav) {
    burger.addEventListener("click", function () {
      var open = d.body.classList.toggle("nav-open");
      burger.setAttribute("aria-expanded", open ? "true" : "false");
    });
    nav.addEventListener("click", function (e) {
      if (e.target && e.target.closest && e.target.closest("a")) {
        d.body.classList.remove("nav-open");
        burger.setAttribute("aria-expanded", "false");
      }
    });
  }

  /* Scroll reveal (cards, sections) with stagger */
  var targets = [];
  var sections = d.querySelectorAll(".ext-lp-sh, .faq, .stats-strip, .rss-cta, .related-box, .layout-sidebar .widget");
  var i;
  for (i = 0; i < sections.length; i++) sections[i].classList.add("wl-reveal");
  var postCards = d.querySelectorAll("#blog .card");
  for (i = 0; i < postCards.length; i++) {
    postCards[i].classList.add("wl-reveal");
    postCards[i].style.transitionDelay = Math.min(i * 70, 280) + "ms";
  }
  targets = d.querySelectorAll(".wl-reveal");
  if (d.body.classList.contains("wl-reduced-motion") || !("IntersectionObserver" in window)) {
    for (i = 0; i < targets.length; i++) targets[i].classList.add("wl-in");
  } else {
    var io = new IntersectionObserver(function (entries) {
      for (var j = 0; j < entries.length; j++) {
        if (entries[j].isIntersecting) {
          entries[j].target.classList.add("wl-in");
          io.unobserve(entries[j].target);
        }
      }
    }, { rootMargin: "0px 0px -40px", threshold: 0.08 });
    for (i = 0; i < targets.length; i++) io.observe(targets[i]);
  }

  /* Reading time estimate on post cards (~200 wpm) */
  var rt = d.querySelectorAll(".wl-readtime");
  for (i = 0; i < rt.length; i++) {
    var len = parseInt(rt[i].getAttribute("data-len"), 10) || 0;
    var min = Math.max(1, Math.round(len / 5 / 200));
    rt[i].textContent = "\u00b7 ~" + min + " min read";
  }

  /* Copy post link (share row) */
  var copyBtn = d.querySelector(".share-row button[data-url]");
  if (copyBtn) {
    copyBtn.addEventListener("click", function () {
      var u = copyBtn.getAttribute("data-url") || window.location.href;
      function done() {
        var old = copyBtn.textContent;
        copyBtn.textContent = "\u2713";
        setTimeout(function () { copyBtn.textContent = old; }, 1400);
      }
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(u).then(done, function () { window.prompt("Copy link:", u); });
      } else {
        window.prompt("Copy link:", u);
      }
    });
  }

  /* Related posts from the first label (Blogger JSON feed) */
  var box = d.getElementById("related-box");
  if (box) {
    var label = box.getAttribute("data-label");
    if (label) {
      var s = d.createElement("script");
      s.src = window.location.protocol + "//" + window.location.host + "/-/" + encodeURIComponent(label) + "?alt=json-in-script&max-results=6";
      window.wlRelated = function (data) {
        var list = d.getElementById("related-list");
        var here = window.location.href.split("#")[0];
        var items = [];
        var feed = data && data.feed;
        var entries = (feed && feed.entry) || [];
        for (var k = 0; k < entries.length && items.length < 4; k++) {
          var en = entries[k], href = "", alt;
          var links = en.link || [];
          for (var l = 0; l < links.length; l++) {
            if (links[l].rel === "alternate") { href = links[l].href; break; }
          }
          if (!href || href.split("#")[0] === here) continue;
          items.push({ t: (en.title && en.title.$t) || "Post", u: href });
        }
        if (items.length && list) {
          list.innerHTML = items.map(function (it) {
            return "<li><a href='" + it.u.replace(/&/g, "&amp;") + "'>" + it.t.replace(/&/g, "&amp;").replace(/</g, "&lt;") + "</a></li>";
          }).join("");
          box.hidden = false;
          box.classList.add("wl-in");
        }
      };
      d.body.appendChild(s);
    }
  }

  /* Professional pack: topbar shrink on scroll */
  var topbarEl = d.querySelector(".topbar");
  function onScrollPro() {
    if (topbarEl) topbarEl.classList.toggle("topbar-shrink", window.scrollY > 40);
  }
  window.addEventListener("scroll", onScrollPro, { passive: true });
  onScrollPro();

  /* Professional pack: 3D card tilt (hover devices only, honors reduced motion) */
  var hoverFine = window.matchMedia && window.matchMedia("(hover: hover) and (pointer: fine)").matches;
  var reducedMo = d.body.classList.contains("wl-reduced-motion");
  function bindTilt(root) {
    if (reducedMo || !hoverFine) return;
    var cards = (root || d).querySelectorAll(".ext-lp-card, #blog .card");
    for (var t = 0; t < cards.length; t++) {
      var c = cards[t];
      if (c.getAttribute("data-tilt")) continue;
      c.setAttribute("data-tilt", "1");
      c.classList.add("wl-tilt");
      (function (card) {
        card.addEventListener("pointermove", function (e) {
          var r = card.getBoundingClientRect();
          var px = (e.clientX - r.left) / r.width - 0.5;
          var py = (e.clientY - r.top) / r.height - 0.5;
          card.style.transform = "perspective(900px) rotateX(" + (-py * 5).toFixed(2) + "deg) rotateY(" + (px * 6).toFixed(2) + "deg) translateY(-4px)";
        });
        card.addEventListener("pointerleave", function () {
          card.style.transform = "";
        });
      })(c);
    }
  }
  bindTilt(d);
  if ("MutationObserver" in window) {
    var tiltObserver = new MutationObserver(function () { bindTilt(d); });
    var catalogRoot = d.getElementById("amo-catalog-root");
    var blogGrid = d.getElementById("blog");
    if (catalogRoot) tiltObserver.observe(catalogRoot, { childList: true });
    if (blogGrid) tiltObserver.observe(blogGrid, { childList: true });
  }
})();
