//
/* ============ EXTENSIONS: SEO pack ============ */
/* ItemList JSON-LD on label / search / archive pages. Safe no-op on home & posts. */
(function () {
  "use strict";
  function injectItemList() {
    var blog = document.getElementById("blog");
    if (!blog) return;
    var cards = blog.querySelectorAll(".card h2 a");
    if (!cards.length) return;
    var items = [];
    for (var i = 0; i < cards.length; i++) {
      var href = cards[i].getAttribute("href");
      var title = (cards[i].textContent || "").trim();
      if (!href || !title) continue;
      items.push({ "@type": "ListItem", position: items.length + 1, url: href, name: title });
    }
    if (!items.length) return;
    var s = document.createElement("script");
    s.type = "application/ld+json";
    s.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "ItemList",
      name: (document.title || "").replace(/\s*(\|[- ]+)?Wer.*$/i, "").trim(),
      numberOfItems: items.length,
      itemListElement: items
    });
    document.head.appendChild(s);
  }
  var isHome = document.getElementById("ext-lp") !== null;
  var isItem = document.querySelector("article.card h1") !== null;
  if (!isHome && !isItem) injectItemList();
})();

/* External SEO API hook. Off by default.
   Zid f head qbel had script:
     window.__WL_SEO__ = { endpoint: "https://your-service/api/seo" };
   Your service receives POST { url } and returns JSON
     { description, keywords }
   which are applied only if the theme did not already emit them. */
(function () {
  "use strict";
  var cfg = window.__WL_SEO__ || {};
  var endpoint = String(cfg.endpoint || "").trim();
  if (!endpoint) return;
  function setMeta(attr, name, content) {
    if (!content) return;
    if (document.head.querySelector(attr + '="' + name + '"')) return;
    var m = document.createElement("meta");
    m.setAttribute(attr, name);
    m.setAttribute("content", content);
    document.head.appendChild(m);
  }
  fetch(endpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ url: location.href }),
    credentials: "omit"
  })
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (data) {
      if (!data) return;
      if (data.description) setMeta("name", "description", data.description);
      if (data.keywords) setMeta("name", "keywords", data.keywords);
    })
    .catch(function () { /* silent */ });
})();
